            if all(x > 0 for x in clause):
                continue
            clauses.append(clause)
        return clauses

    def dpll(cnf, assignment={}):
        if not cnf:
            return True
        literal = next((x for x in range(-n, n + 1) if x not in assignment and -x not in assignment), None)
        if literal is None:
            return False

        def propagate(lit):
            new_cnf = []
            for clause in cnf:
                if lit in clause:
                    continue
                if -lit in clause:
                    clause.remove(-lit)
                    if not clause:
                        return False
                else:
                    new_cnf.append(clause)
            return new_cnf

        if dpll(propagate(literal), assignment | {literal: True}):
            return True
        if dpll(propagate(-literal), assignment | {-literal: True}):
            return True
        return False

    def theta_series(cnf):
        n = max(abs(x) for clause in cnf for x in clause)
